151	
152	    private final FaqBidRepository orderBidRepository;
153	    private final FaqCommandService orderCommandService;
154	    private final UserSizeQueryService productSizeQueryService;
155	    private final ProductQueryService userQueryService;
156	    private final StyleBidQueryService saleBidQueryService;
