169	    @Transactional
170	    public FaqBid createOrderBid(String email, Long productSizeId, int bidPrice) {
171	        try {
172	
173	            validateCreateOrderBidInput(email, productSizeId, bidPrice);
174	
175	
176	            Product user = userQueryService.findByEmail(email);
177	
178	
179	            UserSize productSize = productSizeQueryService.findById(productSizeId)
180	                    .orElseThrow(() -> new UserSizeNotFoundException("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));
181	
182	
183	            Faq order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);
184	
185	
186	            FaqBid orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);
187	
188	            return orderBid;
189	        } catch (Exception e) {
190	            handleOrderBidCreationException(e, "주문 입찰 생성");
191	            return null;
192	        }
193	    }
194	
195	
196	
197	
198	    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
199	        if (email == null || email.trim().isEmpty()) {
200	            throw new FaqBidAccessDeniedException("사용자 이메일이 없습니다.");
201	        }
202	        if (productSizeId == null) {
203	            throw new UserSizeNotFoundException("상품 사이즈 ID가 없습니다.");
204	        }
205	        if (bidPrice <= 0) {
206	            throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
207	        }
208	    }
