213	    private FaqBid createAndSaveOrderBid(Product user, UserSize productSize, int bidPrice, Faq order) {
214	        FaqBid orderBid = FaqBid.builder()
215	                .user(user)
216	                .productSize(productSize)
217	                .bidPrice(bidPrice)
218	                .status(BidStatus.PENDING)
219	                .order(order)
220	                .build();
221	
222	
223	        orderBid.assignOrder(order);
224	
225	        return orderBidRepository.save(orderBid);
226	    }
