241	    @Transactional
242	    public FaqBid createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
243	                                          boolean isWarehouseStorage, NotificationRequestDto paymentRequest) {
244	        try {
245	
246	            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);
247	
248	
249	            Product buyer = userQueryService.findByEmail(buyerEmail);
250	
251	
252	            StyleBid saleBid = getSaleBidAndValidate(saleBidId);
253	            Style sale = saleBid.getSale();
254	
255	
256	            Faq order = orderCommandService.createInstantOrder(
257	                    buyer,
258	                    saleBid,
259	                    addressId,
260	                    isWarehouseStorage,
261	                    paymentRequest
262	            );
263	
264	
265	            FaqBid orderBid = createInstantOrderBid(order, saleBid, sale);
266	
267	            return orderBid;
268	        } catch (Exception e) {
269	            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
270	            return null;
271	        }
272	    }
