277	    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, NotificationRequestDto paymentRequest) {
278	        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
279	            throw new FaqBidAccessDeniedException("구매자 이메일이 없습니다.");
280	        }
281	        if (saleBidId == null) {
282	            throw new StyleBidNotFoundException("판매 입찰 ID가 없습니다.");
283	        }
284	        if (addressId == null) {
285	            throw new InvalidFaqBidDataException("배송지 ID가 없습니다.");
286	        }
287	        if (paymentRequest == null) {
288	            throw new InvalidNotificationAddressDataException("결제 정보가 없습니다.");
289	        }
290	    }
