295	    private StyleBid getSaleBidAndValidate(Long saleBidId) {
296	        StyleBid saleBid = saleBidQueryService.findById(saleBidId);
297	        if (saleBid == null) {
298	            throw new StyleBidNotFoundException("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
299	        }
300	
301	        Style sale = saleBid.getSale();
302	        if (sale == null) {
303	            throw new InvalidFaqBidDataException("판매 입찰과 연결된 판매 정보가 없습니다.");
304	        }
305	
306	        return saleBid;
307	    }
