312	    private FaqBid createInstantOrderBid(Faq order, StyleBid saleBid, Style sale) {
313	        UserSize productSize = saleBid.getProductSize();
314	
315	        FaqBid orderBid = FaqBid.builder()
316	                .user(order.getUser())
317	                .productSize(productSize)
318	                .bidPrice(saleBid.getBidPrice())
319	                .status(BidStatus.MATCHED)
320	                .order(order)
321	                .sale(sale)
322	                .build();
323	
324	
325	        orderBid.assignOrder(order);
326	
327	
328	        orderBid.markAsInstantPurchase();
329	        return orderBidRepository.save(orderBid);
330	    }
