335	    private void handleOrderBidCreationException(Exception e, String operation) {
336	        if (e instanceof FaqException) {
337	            throw (FaqException) e;
338	        }
339	        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
340	        throw new FaqBidCreationFailedException(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
341	    }
