350	    @Transactional
351	    public void matchOrderBid(FaqBid orderBid) {
352	        try {
353	            if (orderBid == null) {
354	                throw new FaqBidNotFoundException("주문 입찰 정보가 없습니다.");
355	            }
356	
357	            if (orderBid.getStatus() == BidStatus.MATCHED) {
358	                throw new FaqBidAlreadyMatchedException("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
359	            }
360	
361	            orderBid.updateStatus(BidStatus.MATCHED);
362	        } catch (Exception e) {
363	            if (e instanceof FaqException) {
364	                throw e;
365	            }
366	            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
367	            throw new FaqBidMatchingFailedException("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
368	        }
369	    }
370	
371	
372	
