379	    @Transactional
380	    public void deleteOrderBid(Long orderBidId) {
381	        try {
382	
383	            FaqBid orderBid = orderBidRepository.findById(orderBidId)
384	                    .orElseThrow(() -> new FaqBidNotFoundException("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));
385	
386	
387	            if (orderBid.getSale() != null) {
388	                throw new FaqBidAlreadyMatchedException("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
389	            }
390	
391	
392	            if (orderBid.getStatus() == BidStatus.MATCHED) {
393	                throw new FaqBidAlreadyMatchedException("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
394	            }
395	
396	
397	            if (orderBid.getOrder() != null) {
398	                orderCommandService.deleteOrder(orderBid.getOrder().getId());
399	            }
400	
401	
402	            orderBidRepository.delete(orderBid);
403	        } catch (Exception e) {
404	            if (e instanceof FaqException) {
405	                throw e;
406	            }
407	            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
408	            throw new FaqBidDeletionFailedException("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
409	        }
410	    }
