 57	    public Notification processPayment(Faq order, Product user, NotificationRequestDto requestDto) {
 58	        Instant start = Instant.now();
 59	        try {
 60	            validatePaymentRequest(order, user, requestDto);
 61	
 62	            log.info("결제 처리 시작: 주문ID={}, 사용자={}, 결제유형={}",
 63	                    order.getId(), user.getEmail(), requestDto.getResolvedPaymentType());
 64	
 65	            Notification payment;
 66	
 67	            switch (requestDto.getResolvedPaymentType()) {
 68	                case "CARD":
 69	                    payment = createCardPayment(order, user, (CardNotificationRequestDto) requestDto);
 70	                    break;
 71	                case "ACCOUNT":
 72	                    payment = createAccountPayment(order, user, (AccountNotificationRequestDto) requestDto);
 73	                    break;
 74	                case "GENERAL":
 75	                    payment = createGeneralPayment(order, user, (GeneralNotificationRequestDto) requestDto);
 76	                    break;
 77	                default:
 78	                    throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
 79	                            "유효하지 않은 결제 유형: " + requestDto.getPaymentType());
 80	            }
 81	
 82	
 83	            notifyUsersAndUpdateSaleStatus(order, payment);
 84	
 85	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
 86	                    order.getId(), payment.getId(), payment.getStatus());
 87	
 88	            return payment;
