     3	public enum NotificationStatus {
     4	    PENDING,
     5	    PAID,
     6	    REFUND_REQUESTED,
     7	    REFUNDED,
     8	    FAILED;
     9	
    10	    public boolean canTransitionTo(NotificationStatus newStatus) {
    11	        switch (this) {
    12	            case PENDING:
    13	                return newStatus == PAID;
    14	            case PAID:
    15	                return newStatus == REFUND_REQUESTED || newStatus == REFUNDED;
    16	            case REFUND_REQUESTED:
    17	                return newStatus == REFUNDED;
    18	            default:
    19	                return false;
    20	        }
    21	    }
    22	}
